/**
 * Check if the provided email address is valid. For example, abc.123@def.ghi.com.uk is a valid email address. Cover as many cases as possible to avoid false negatives.
 *
 * @param {string} email - The email to check.
 * @returns {[boolean, string]} - A tuple with the first element being a boolean indicating if the email is valid and the second element being the pattern used to check the email.
 */
const checkEmail = (email) => {
  // This regex is a widely accepted and robust pattern for email validation.
  // It aims to balance RFC compliance with practical usability and security.
  // It covers:
  // - Standard characters in the local part (before @).
  // - Dots in the local part, but not at the beginning or end, and not consecutively.
  // - Quoted strings in the local part.
  // - Domain names with subdomains.
  // - Domain names with hyphens.
  // - IP address literals as domains (IPv4 and a simplified IPv6-like structure).
  // - Case-insensitivity.
  //
  // While perfect email validation is notoriously complex and often requires
  // more than just a regex (e.g., DNS checks), this pattern is a strong
  // and commonly used approach to catch most invalid formats and avoid
  // common pitfalls like ReDoS.
  const emailRegex = new RegExp(
    /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/i
  );

  const patternUsed = emailRegex.source;
  const isValid = emailRegex.test(email);

  return [isValid, patternUsed];
};
